 private void asset(LinearLayout p,String path,int height){if(path.startsWith("media/rarities/v2/")){String key=path.substring(path.lastIndexOf('/')+1).replace(".png","");String[] keys={"common","rare","super-rare","epic","mythic"};int tier=0;for(int i=0;i<keys.length;i++)if(keys[i].equals(key))tier=i;p.addView(new RarityBadgeView(this,tier),new LinearLayout.LayoutParams(-1,dp(Math.max(36,height))));return;}ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setContentDescription(path);p.addView(v,new LinearLayout.LayoutParams(-1,dp(height)));loadLocalImage(v,path);}
 private Bitmap decodeLocal(String path)throws IOException{
  Bitmap known=cache.get(path);if(known!=null)return known;
  BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;
  try(InputStream in=getAssets().open(path)){BitmapFactory.decodeStream(in,null,options);}
  if(options.outWidth<=0||options.outHeight<=0)throw new IOException("Invalid image: "+path);
  options.inSampleSize=1;while(options.outWidth/options.inSampleSize>800||options.outHeight/options.inSampleSize>800)options.inSampleSize*=2;
  options.inJustDecodeBounds=false;Bitmap bitmap;
  try(InputStream in=getAssets().open(path)){bitmap=BitmapFactory.decodeStream(in,null,options);}
  if(bitmap==null)throw new IOException("Could not decode: "+path);
  cache.put(path,bitmap);return bitmap;
 }
 private Bitmap imageMessage(String message){
  Bitmap b=Bitmap.createBitmap(320,100,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);paint.setColor(gold);paint.setTextSize(18);paint.setTextAlign(Paint.Align.CENTER);canvas.drawText(message,160,55,paint);return b;
 }
 private void loadLocalImage(ImageView view,String path){
  Bitmap known=cache.get(path);if(known!=null){view.setImageBitmap(known);return;}
  view.setImageBitmap(imageMessage("Loading image…"));
  localImages.execute(()->{Bitmap bitmap=null;String failure=null;
   try{bitmap=decodeLocal(path);}catch(Exception ex){failure=path+": "+ex.getClass().getSimpleName();android.util.Log.w("GenesisAssets",failure,ex);if(path.startsWith("media/races/")&&!path.endsWith("/unknown.png"))try{bitmap=decodeLocal("media/races/unknown.png");}catch(Exception ignored){}}
   final Bitmap result=bitmap;final String error=failure;
   runOnUiThread(()->{if(isDestroyed())return;view.setImageBitmap(result==null?imageMessage("Image unavailable"):result);view.setContentDescription(error==null?path:"Image unavailable: "+path);view.requestLayout();view.invalidate();});
  });
 }
 private void checkBundledImages(){
  task(()->{JSONObject manifest=new JSONObject(assetText("image-manifest.json"));JSONArray paths=manifest.names();int ok=0;StringBuilder failed=new StringBuilder();for(int i=0;paths!=null&&i<paths.length();i++){String path=paths.getString(i);try{decodeLocal(path);ok++;}catch(Exception ex){failed.append("\n").append(path);}}return ok+" bundled images decoded."+(failed.length()==0?"\nAll required images are readable in this APK.":"\nMissing or unreadable:"+failed);},x->alert(String.valueOf(x)));
 }

 interface Work{Object run()throws Exception;}interface Done{void run(Object value)throws Exception;}
 private void task(Work work,Done done){if(busy)return;busy=true;status.setText("Connecting to Genesis…");showLoading();worker.execute(()->{try{Object x=work.run();runOnUiThread(()->{if(isDestroyed())return;busy=false;hideLoading();try{done.run(x);}catch(Exception e){alert("Could not display the response. Refresh to reload.");}});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;busy=false;hideLoading();if(!api.signedIn())login();else if(!ready){body.removeAllViews();heading("Connection needs attention");note("Check your connection and the existing Genesis backend configuration, then retry.");button(body,"Try again",()->task(()->{refresh();return null;},x->render()));button(body,"Sign out",this::logout);}status.setText("Connection interrupted");alert(e.getMessage()==null?"Request failed. Please retry.":e.getMessage());});}});}
 private JSONObject rpc(String name,JSONObject args)throws Exception{return api.rpc(name,args);}
 private void refresh()throws Exception{
  JSONObject p=rpc("genesis_profile_ensure",new JSONObject());JSONObject s=rpc("genesis_secure_snapshot",new JSONObject());
  if(!s.optBoolean("initialized")){rpc("genesis_wallet_initialize",json("p_initial_gp",0,"p_initial_essence",0));s=rpc("genesis_secure_snapshot",new JSONObject());}
  rpc("genesis_verify_achievements",json("p_request_key",UUID.randomUUID().toString()));
  JSONObject m=rpc("genesis_meta_snapshot",new JSONObject());s=rpc("genesis_secure_snapshot",new JSONObject());
  economy=rpc("genesis_v2_status",new JSONObject());
  // Page through RLS-protected rows; avoid the legacy snapshot's 1000-character ceiling.
  JSONArray rows=new JSONArray();int offset=0;
  while(true){JSONArray batch=arr(api.get("/rest/v1/genesis_characters?select=*&or=(archived.eq.false,selection_state.eq.pending)&order=created_at.desc,registry_id.desc&limit=500&offset="+offset),"items");for(int i=0;i<batch.length();i++)rows.put(batch.getJSONObject(i));if(batch.length()<500)break;offset+=batch.length();}
  JSONObject snap=rpc("genesis_collection_snapshot",json("p_limit",1,"p_history_limit",200));
  JSONArray artwork=arr(api.get("/rest/v1/genesis_character_media?select=registry_id,storage_path,updated_at&limit=1000"),"items");
  JSONArray built=new JSONArray(),waiting=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);JSONObject c=new JSONObject(engine.call("nativeReconstruct",row.toString()));if(row.optString("selection_state").equals("pending"))waiting.put(c);else built.put(c);}pending=waiting;
  s.put("wallet",obj(economy,"wallet"));profile=p;secure=s;meta=m;characters=built;history=arr(snap,"history");media=artwork;ready=true;
 }
 private void mutate(String name,JSONObject args,boolean receipt){final JSONObject before=current();if(receipt){try{args.put("p_request_key",UUID.randomUUID().toString());}catch(JSONException ignored){}}task(()->{JSONObject result;try{result=rpc(name,args);}catch(IOException e){if(!receipt)throw e;result=rpc(name,args);}try{refresh();}catch(Exception ex){throw new IOException("The action may have completed. Refresh before trying again. "+ex.getMessage());}return result;},x->{JSONObject result=(JSONObject)x;if(result.has("results")){reveal(arr(result,"results"));return;}render();if(before!=null&&(name.equals("genesis_character_train")||name.equals("genesis_character_ascend")||name.startsWith("genesis_character_upgrade_"))){JSONObject after=current();if(after!=null)presentation.progression(name.equals("genesis_character_train")?"train":name.equals("genesis_character_ascend")?"evolution":"upgrade",before,after,name.endsWith("_weapon")?"weapon":args.optString("p_slot","weapon"));else alert("Saved to your account.");}else alert("Saved to your account.");});}
 private void login(){headerBar.setVisibility(View.VISIBLE);backButton.setVisibility(View.GONE);root.setBackgroundColor(bg);body.removeAllViews();nav.removeAllViews();navScroll.setVisibility(View.GONE);ready=false;status.setText("ACCOUNT ACCESS");LinearLayout saved=body;LinearLayout[] panes=workspacePanels();asset(panes[0],"media/branding/genesis-logo.png",145);text(panes[0],"CHARACTER CHRONICLES",18,gold);text(panes[0],"Your characters. Your chronicles. One account.",14,muted);body=panes[1];try{heading("Enter the Sanctum");if(!Api.configured()){note("Backend not configured. Check SUPABASE_URL and SUPABASE_PUBLISHABLE_KEY in repository Variables, then rebuild.");return;}EditText email=input(body,"Email",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),pass=input(body,"Password",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);button(body,"Sign in",()->authenticate(email,pass,false));button(body,"Create account",()->authenticate(email,pass,true));note("Confirm your email if requested, then sign in. Sessions are securely stored on this device.");}finally{body=saved;}}

 private void authenticate(EditText e,EditText p,boolean signup){String email=e.getText().toString().trim(),password=p.getText().toString();if(email.isEmpty()||password.isEmpty()){alert("Enter your email and password.");return;}task(()->{boolean ok=api.authenticate(email,password,signup);if(ok)refresh();return ok;},x->{p.setText("");if(Boolean.TRUE.equals(x)){page="Lobby";render();}else alert("Check your email for confirmation, then sign in.");});}
 private void logout(){task(()->{api.logout();return null;},x->{profile=new JSONObject();characters=new JSONArray();history=new JSONArray();media=new JSONArray();cache.evictAll();selected="";activeSummons.clear();summonChoices.clear();pending=new JSONArray();page="Lobby";login();});}
 private JSONObject current(){for(int i=0;i<characters.length();i++){JSONObject c=characters.optJSONObject(i);if(c.optString("serverRegistryId").equals(selected))return c;}return null;}
 private String name(JSONObject c){String n=c.optString("customName","").trim();return n.isEmpty()?"UNNAMED HERO":n;}
 private void gotoPage(String p){page=p;pageSize=30;render();contentScroll.post(()->contentScroll.scrollTo(0,0));}
 private void render(){if(livingScene!=null){livingScene.stop();livingScene=null;}if(embeddedSanctum!=null){embeddedSanctum.pause();embeddedSanctum=null;}if(sanctum!=null){sanctum.setRunning(false);sanctum=null;}body.removeAllViews();nav.removeAllViews();if(!ready){login();return;}headerBar.setVisibility(View.VISIBLE);root.setBackgroundColor(bg);backButton.setVisibility(View.VISIBLE);navScroll.setVisibility(View.GONE);if(page.equals("Home"))page="Lobby";JSONObject wallet=obj(secure,"wallet");status.setText(profile.optString("display_name","Summoner")+"  |  "+wallet.optLong("gp")+" GP  |  "+wallet.optLong("essence")+" Essence");switch(page){case "Lobby":lobby();break;case "Sanctum":home();break;case "Collection":collection();break;case "Review":review();break;case "Progression":progression();break;case "Prompt":prompt();break;case "Codex":codex();break;case "Daily":daily();break;case "Shop":shop();break;case "Achievements":achievements();break;case "Profile":profilePage();break;case "History":historyPage();break;case "Settings":settings();break;case "Detail":detail();break;case "More":more();break;default:lobby();}}
 private LinearLayout[] workspacePanels(){LinearLayout row=new LinearLayout(this);body.addView(row,new LinearLayout.LayoutParams(-1,dp(Math.max(230,getResources().getConfiguration().screenHeightDp-86))));LinearLayout[] panes=new LinearLayout[2];for(int i=0;i<2;i++){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-1,i==0?.9f:1.1f);lp.setMargins(dp(3),0,dp(3),0);row.addView(scroll,lp);panes[i]=new LinearLayout(this);panes[i].setOrientation(LinearLayout.VERTICAL);panes[i].setPadding(dp(12),dp(12),dp(12),dp(12));panes[i].setBackground(new PixelFrame(this,panel,gold));scroll.addView(panes[i]);}return panes;}
 private LinearLayout gridCell(LinearLayout[] row,int index,int columns){if(index%columns==0){row[0]=new LinearLayout(this);row[0].setWeightSum(columns);body.addView(row[0],new LinearLayout.LayoutParams(-1,-2));}LinearLayout cell=new LinearLayout(this);cell.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row[0].addView(cell,lp);return cell;}
