 private String reward(JSONObject r){List<String> a=new ArrayList<>();for(String k:new String[]{"gp","essence","xp"})if(r.optLong(k)>0)a.add(r.optLong(k)+" "+k.toUpperCase(Locale.ROOT));return android.text.TextUtils.join(" + ",a);}
 private void daily(){heading("Daily rewards");note("Server date: "+economy.optString("server_date")+" · Resets at 00:00 UTC. GP and tickets do not expire. No streak penalty.");String[] ids={"checkin","summon1","summon3","train1","upgrade1"};String[] titles={"Daily check-in","Summon 1 character","Summon 3 characters","Train once","Upgrade once"};String[] rewards={"60 GP + 50 Essence + 10 Tokens + 1 Ticket","12 GP","24 GP","12 GP + 15 Essence","12 GP + 20 Essence"};LinearLayout[] gridRow={null};int columns=gridColumns();JSONArray claims=arr(economy,"claims");for(int i=0;i<ids.length;i++){final String id=ids[i];int target=i==2?3:1;boolean claimed=false;for(int j=0;j<claims.length();j++)if(id.equals(claims.optString(j)))claimed=true;LinearLayout box=card(gridCell(gridRow,i,columns));text(box,titles[i],18,gold);text(box,rewards[i],14,muted);int progress=obj(economy,"progress").optInt(id);text(box,Math.min(progress,target)+" / "+target,13,white);button(box,claimed?"Claimed":"Claim reward",()->mutate("genesis_v2_claim",json("p_mission",id),true)).setEnabled(!claimed&&progress>=target);}}
 private void shop(){heading("Exchange Shop");int tokens=obj(economy,"wallet").optInt("tokens");note(tokens+" Genesis Tokens · Earned through Daily rewards");note("Fixed items and prices. No random boxes or chance boosts.");String[] ids={"essence50","essence150"};int[] costs={5,12},amounts={50,150};for(int i=0;i<ids.length;i++){final String id=ids[i];final int cost=costs[i],amount=amounts[i];button(body,amount+" Essence · "+cost+" Tokens",()->new AlertDialog.Builder(this).setTitle("Confirm exchange").setMessage("Exchange "+cost+" Tokens for "+amount+" Essence?").setNegativeButton("Cancel",null).setPositiveButton("Exchange",(d,w)->mutate("genesis_v2_shop_buy",json("p_item",id),true)).show()).setEnabled(tokens>=cost);}}
 private void profilePage(){heading("Summoner profile");LinearLayout saved=body;LinearLayout[] panes=workspacePanels();body=panes[0];try{note(profile.optString("player_id"));EditText name=input(body,"Display name",InputType.TYPE_CLASS_TEXT);name.setText(profile.optString("display_name"));name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(28)});button(body,"Save display name",()->mutate("genesis_profile_ensure",json("p_display_name",name.getText().toString()),false));body=panes[1];JSONObject p=obj(meta,"profile");note("Level "+p.optInt("summoner_level",1)+" · Lifetime EXP "+p.optLong("summoner_xp"));note(p.optInt("achievement_points")+" AP · "+p.optString("achievement_rank"));JSONObject stats=obj(meta,"stats");for(String k:new String[]{"total_summons","ten_pulls","highest_combat_power","highest_weapon_power","daily_mission_claims","perfect_daily_days","full_login_cycles"})note(k.replace('_',' ')+": "+stats.optLong(k));button(body,"Sign out",this::logout);}finally{body=saved;}}
 private void historyPage(){heading("History & economy ledger");note("Latest 200 characters and 10 economy events");JSONArray ledger=arr(secure,"ledger");for(int i=0;i<ledger.length();i++){JSONObject e=ledger.optJSONObject(i);text(card(body),e.optString("event_type")+"\nGP "+e.optLong("gp_delta")+" · Essence "+e.optLong("essence_delta")+"\n"+e.optString("created_at"),14,muted);}for(int i=0;i<Math.min(pageSize,history.length());i++){JSONObject h=history.optJSONObject(i);LinearLayout box=card(body);asset(box,"media/rarities/"+(h.optString("seed").startsWith("G165-")?"v2/":"")+slug(h.optString("rarity_name"))+".png",70);text(box,h.optString("character_id")+"\n"+h.optString("created_at")+(h.optBoolean("archived")?"\nArchived":""),14,white);}if(pageSize<history.length())button(body,"Load more",()->{pageSize+=30;render();});}
 private void volume(String label,String key,int defaultValue){
  TextView value=text(body,label+": "+prefs.getInt(key,defaultValue)+"%",14,muted);
  SeekBar bar=new SeekBar(this);bar.setMax(100);bar.setProgress(prefs.getInt(key,defaultValue));bar.setContentDescription(label);body.addView(bar,new LinearLayout.LayoutParams(-1,dp(48)));
  bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int progress,boolean fromUser){value.setText(label+": "+progress+"%");if(fromUser){prefs.edit().putInt(key,progress).apply();audio.settingsChanged();}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});
 }
 private void settings(){heading("Settings");button(body,"Preview new rarity badges",()->{ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list);for(int i=0;i<5;i++)list.addView(new RarityBadgeView(this,i),new LinearLayout.LayoutParams(dp(290),dp(64)));new AlertDialog.Builder(this).setTitle("Rarity badges").setView(scroll).setPositiveButton("Close",null).show();});button(body,"Check bundled images",this::checkBundledImages);toggle("Background music","music",true);volume("Music volume","musicVolume",35);toggle("Sound effects","sound",true);volume("Effects volume","sfxVolume",65);button(body,"Preview rarity effects",()->new AlertDialog.Builder(this).setTitle("Choose rarity effect").setItems(new String[]{"Common","Rare","Super Rare","Epic","Mythic"},(d,i)->presentation.preview(new int[]{0,2,4,6,8}[i])).show());toggle("Reduce motion","reduceMotion",false);toggle("Compact collection","compact",false);button(body,"Refresh account",()->task(()->{refresh();return null;},x->render()));button(body,"Sign out",this::logout);note("Genesis 18.2 · Living UI\nProgress and artwork are stored in your online account. This app stores only encrypted session tokens and display preferences locally.");}
